const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const region = ee.Geometry.Polygon([
    [-83.0, 41.0], // Southwestern tip near Detroit
    [-73.0, 41.0], // Eastern tip of New York
    [-73.0, 45.0], // Northern tip of New York
    [-83.0, 45.0]  // Northwestern tip near Lake Huron
  ]);

  const date1_str = '2020-02-22';
  const date2_str = '2020-03-01';

  // Function to get and process MODIS snow cover data
  const getSnowCover = (date) => {
    const start = ee.Date(date);
    const end = start.advance(1, 'day'); // Get data for the specific day

    let collection = ee.ImageCollection('MODIS/006/MOD10A1')
      .filterDate(start, end)
      .filterBounds(region);

    if (collection.size().getInfo() === 0) {
      console.log(`No MODIS images found for ${date}.`);
      return null;
    }

    const image = collection.first();
    const snowCover = image.select('NDSI_Snow_Cover');

    // Mask out non-snow/cloud/water pixels
    // NDSI_Snow_Cover values: 0-100 (snow percentage), 200 (missing), 201 (no decision),
    // 250 (night), 253 (lake), 254 (cloud), 255 (fill)
    const validSnowMask = snowCover.gte(0).and(snowCover.lte(100)); // Real snow percentages
    const cloudMask = snowCover.neq(254);
    const waterMask = snowCover.neq(253);
    const nightMask = snowCover.neq(250);
    const noDecisionMask = snowCover.neq(201);
    const missingMask = snowCover.neq(200);
    const fillMask = snowCover.neq(255);

    // Combine masks to get valid observable land pixels
    const observableMask = cloudMask.and(waterMask).and(nightMask).and(noDecisionMask).and(missingMask).and(fillMask);
    const maskedSnowCover = snowCover.updateMask(observableMask);

    // Create a binary snow mask (1 for snow, 0 for no snow)
    const binarySnow = maskedSnowCover.gt(0);

    return { image: binarySnow, originalImage: image, maskedSnowCover: maskedSnowCover };
  };

  // Process data for date 1
  const data1 = getSnowCover(date1_str);
  if (!data1) {
    console.log("Failed to retrieve data for Feb 22, 2020.");
    console.log("C1");
    return;
  }

  // Process data for date 2
  const data2 = getSnowCover(date2_str);
  if (!data2) {
    console.log("Failed to retrieve data for Mar 1, 2020.");
    console.log("C1");
    return;
  }

  // Calculate snow-covered area fraction
  const calculateSnowFraction = (img, date) => {
    // Reducer to count total valid pixels and snow pixels
    const stats = img.reduceRegion({
      reducer: ee.Reducer.count().addReducer(ee.Reducer.sum()), // count total valid, sum of snow pixels
      geometry: region,
      scale: 500, // MODIS resolution
      maxPixels: 1e9
    });

    const totalValidPixels = stats.get('count').getInfo();
    const snowPixels = stats.get('sum').getInfo();

    if (totalValidPixels === null || snowPixels === null) {
      console.log(`Calculation failed for ${date}: totalValidPixels=${totalValidPixels}, snowPixels=${snowPixels}`);
      return null;
    }

    if (totalValidPixels === 0) {
      console.log(`No valid observable pixels for ${date} after masking.`);
      return 0; // No valid pixels, so 0 snow fraction
    }

    const snowFraction = (snowPixels / totalValidPixels) * 100; // Percentage
    return snowFraction;
  };

  const snowFraction1 = calculateSnowFraction(data1.image, date1_str);
  const snowFraction2 = calculateSnowFraction(data2.image, date2_str);

  if (snowFraction1 === null || snowFraction2 === null) {
    console.log("C3");
    return;
  }

  // Get cloud percentage for validation
  const cloudCount1 = data1.originalImage.select('NDSI_Snow_Cover').eq(254).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 500,
    maxPixels: 1e9
  }).get('NDSI_Snow_Cover').getInfo();
  const totalCount1 = data1.originalImage.select('NDSI_Snow_Cover').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 500,
    maxPixels: 1e9
  }).get('NDSI_Snow_Cover').getInfo();
  const cloudPercent1 = totalCount1 > 0 ? (cloudCount1 / totalCount1) * 100 : 0;

  const cloudCount2 = data2.originalImage.select('NDSI_Snow_Cover').eq(254).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 500,
    maxPixels: 1e9
  }).get('NDSI_Snow_Cover').getInfo();
  const totalCount2 = data2.originalImage.select('NDSI_Snow_Cover').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 500,
    maxPixels: 1e9
  }).get('NDSI_Snow_Cover').getInfo();
  const cloudPercent2 = totalCount2 > 0 ? (cloudCount2 / totalCount2) * 100 : 0;

  console.log(`Feb 22, 2020: Snow cover fraction = ${snowFraction1.toFixed(2)}%, Cloud % = ${cloudPercent1.toFixed(2)}%`);
  console.log(`Mar 1, 2020: Snow cover fraction = ${snowFraction2.toFixed(2)}%, Cloud % = ${cloudPercent2.toFixed(2)}%`);

  if (snowFraction1 === 0 && snowFraction2 === 0) {
      console.log("No valid snow pixels found for either date after processing.");
      console.log("C2");
      return;
  }


  if (snowFraction2 > snowFraction1) {
    console.log("A"); // More snow on March 1
  } else {
    console.log("B"); // Not more snow on March 1
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
